package com.example.application_service.client;
import com.example.application_service.exception.ApiException;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.stereotype.Component;import org.springframework.web.client.*;import java.net.http.HttpClient;import java.time.*;import java.util.UUID;import java.util.concurrent.atomic.*;import java.util.function.Supplier;
@Component public class InternalServiceClient{private final RestClient jobs,users;private final String token;private final Circuit jobCircuit,userCircuit;public InternalServiceClient(@Value("${application-service.job-service-url}")String jobUrl,@Value("${application-service.user-service-url}")String userUrl,@Value("${application-service.connect-timeout}")Duration connect,@Value("${application-service.read-timeout}")Duration read,@Value("${application-service.internal-token}")String token,@Value("${application-service.circuit-breaker.failure-threshold}")int threshold,@Value("${application-service.circuit-breaker.open-duration}")Duration open){var http=HttpClient.newBuilder().connectTimeout(connect).build();var factory=new JdkClientHttpRequestFactory(http);factory.setReadTimeout(read);jobs=RestClient.builder().baseUrl(jobUrl).requestFactory(factory).build();users=RestClient.builder().baseUrl(userUrl).requestFactory(factory).build();this.token=token;jobCircuit=new Circuit(threshold,open);userCircuit=new Circuit(threshold,open);}
 public JobSnapshot job(UUID id,String trace){try{return call(jobCircuit,()->jobs.get().uri("/internal/jobs/{id}/eligibility",id).header("X-Internal-Token",token).header("X-Correlation-ID",trace).retrieve().body(JobEnvelope.class)).data;}catch(HttpClientErrorException.NotFound e){throw new ApiException(HttpStatus.NOT_FOUND,"JOB_NOT_FOUND","Job was not found");}}
 public CvSnapshot cv(UUID id,UUID candidate,String trace){try{return call(userCircuit,()->users.get().uri(u->u.path("/internal/cvs/{id}/validation").queryParam("candidateId",candidate).build(id)).header("X-Internal-Token",token).header("X-Correlation-ID",trace).retrieve().body(CvEnvelope.class)).data;}catch(HttpClientErrorException.NotFound e){throw new ApiException(HttpStatus.NOT_FOUND,"CV_NOT_FOUND","CV was not found or does not belong to the candidate");}}
 public void requireCompany(UUID company,UUID user,String trace){try{CompanySnapshot x=call(userCircuit,()->users.get().uri(u->u.path("/internal/companies/{id}/authorization").queryParam("userId",user).build(company)).header("X-Internal-Token",token).header("X-Correlation-ID",trace).retrieve().body(CompanyEnvelope.class)).data;if(x==null||!x.canManage)throw new ApiException(HttpStatus.FORBIDDEN,"RESOURCE_FORBIDDEN","You cannot manage applications for this job");}catch(HttpClientErrorException.NotFound e){throw new ApiException(HttpStatus.FORBIDDEN,"RESOURCE_FORBIDDEN","You cannot manage applications for this job");}}
 private <T> T call(Circuit circuit,Supplier<T> request){if(circuit.open())throw unavailable("Dependency circuit is open");for(int attempt=0;attempt<2;attempt++){try{T result=request.get();if(result==null)throw new RestClientException("Empty internal response");circuit.success();return result;}catch(HttpClientErrorException e){throw e;}catch(ResourceAccessException e){if(attempt==1){circuit.failure();Throwable c=e;while(c!=null){if(c instanceof java.net.http.HttpTimeoutException)throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"DEPENDENCY_TIMEOUT","Dependency timed out");c=c.getCause();}throw unavailable("Dependency is unavailable");}}catch(RestClientException e){if(attempt==1){circuit.failure();throw unavailable("Dependency returned an invalid response");}}}throw unavailable("Dependency is unavailable");}
 private ApiException unavailable(String message){return new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"DEPENDENCY_UNAVAILABLE",message);}static final class Circuit{private final int threshold;private final long openMillis;private final AtomicInteger failures=new AtomicInteger();private final AtomicLong openedAt=new AtomicLong();Circuit(int t,Duration d){threshold=t;openMillis=d.toMillis();}boolean open(){long at=openedAt.get();if(at==0)return false;if(System.currentTimeMillis()-at>=openMillis){openedAt.compareAndSet(at,0);failures.set(0);return false;}return true;}void success(){failures.set(0);openedAt.set(0);}void failure(){if(failures.incrementAndGet()>=threshold)openedAt.compareAndSet(0,System.currentTimeMillis());}}
 public static class JobEnvelope{public boolean success;public JobSnapshot data;}public static class JobSnapshot{public UUID jobId,companyId,createdBy;public String title,status;public LocalDate applicationDeadline;public boolean acceptingApplications;public long version;}public static class CvEnvelope{public boolean success;public CvSnapshot data;}public static class CvSnapshot{public UUID cvId,candidateId;public String fileName,objectKey,contentType;public long sizeBytes;public boolean valid;}public static class CompanyEnvelope{public boolean success;public CompanySnapshot data;}public static class CompanySnapshot{public boolean canManage;public String memberRole;}}
